'use strict';
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const defaults=()=>({profile:{name:'',age:'',pronouns:'',city:'',gender:'',orientation:'',goal:'Friendship first',structure:'Monogamy',bio:'',access:'',values:'',lifestyle:'',children:'',faith:''},prefs:{},saved:[],blocked:[],reports:[],messages:{},boundaries:{},settings:{remember:false,discreet:false,paused:false},custom:[],overrides:{},date:{},almanac:{events:[],notes:[],tasks:[],calendar:12,commandHistory:[]}});
let state=defaults();try{let saved=JSON.parse(localStorage.getItem('tada-demo'));if(saved&&saved.settings?.remember)state={...state,...saved}}catch{}
let viewMode='buttons',sortMode='Category',previewAudience='On my profile';
let category='All',query='',prefFilter='All preferences',personQuery='',distance=200,goal='All intentions',structure='All structures',conversation='alex',page='discover';
const nav=[['interests','✺','Interests & desires'],['discover','✧','Discover'],['advisor','✦','Nathan AI 🚀'],['board','▤','My buttons'],['profile','◉','My whole self'],['intent','◷','My intention now'],['saved','♡','Saved connections'],['messages','◌','Conversations'],['boundaries','◇','Consent & boundaries'],['planner','▦','Date planner'],['safety','⊕','Respect & safety'],['learn','↗','Learn & resources'],['settings','⚙','Privacy & settings'],['almanac','☼','The Tabor Almanac'],['knowledge','▥','TORMO library']];
function persist(){if(state.settings.remember){try{localStorage.setItem('tada-demo',JSON.stringify(state))}catch{toast('Browser storage unavailable. Changes stay in this session.')}}else localStorage.removeItem('tada-demo');$('#username').textContent=state.profile.name||'Your profile';document.body.classList.toggle('discreet',state.settings.discreet)}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3300)}
function options(list,selected){return list.map(v=>`<option${v===selected?' selected':''}>${esc(v)}</option>`).join('')}
function title(eyebrow,h,description){return `<div class="eyebrow" style="color:#9c6287;margin-bottom:14px">${eyebrow}</div><h1>${h}</h1><p class="intro">${description}</p>`}
function go(p){location.hash=p;if(page===p)render()}
function allInterests(){return [...interests.map(i=>({...i,...(state.overrides?.[i.id]||{})})),...state.custom]}
function modal(html){$('#modal').innerHTML=`<button class="close" aria-label="Close dialog" onclick="document.querySelector('#modal').close()">×</button>${html}`;$('#modal').showModal()}
function empty(text){return `<div class="empty">${text}</div>`}
function personCard(p){const shared=p.tags.filter(t=>state.prefs[interests.find(i=>i.name===t)?.id]?.interest==='Interested');return `<article class="card"><div class="profileart ${p.style}"><span class="sample">ILLUSTRATIVE PROFILE</span><span aria-hidden="true">${p.symbol}</span><button class="heart" data-save="${p.id}" aria-label="${state.saved.includes(p.id)?'Unsave':'Save'} ${p.name}" aria-pressed="${state.saved.includes(p.id)}">${state.saved.includes(p.id)?'♥':'♡'}</button></div><div class="profiletop"><h3>${p.name}, ${p.age}</h3><span class="badge">${shared.length?shared.length+' shared interests':'Explore together'}</span></div><small>${p.pronouns} · ${p.city} · ${p.distance} mi*</small><div class="tags">${p.tags.map(t=>`<span class="tag">${t}</span>`).join('')}</div><p class="desc">${p.bio}</p><button class="outline full" data-person="${p.id}">Meet ${p.name} <span aria-hidden="true">↗</span></button></article>`}
function discover(){return `<section class="hero"><div><div class="eyebrow">LESS GUESSING. MORE CONNECTION.</div><h1>Your people.<br><em>Your kind of different.</em></h1><p>No guessing games. No squeezing yourself into a box.<br>A little more honesty. A lot more you.</p><button data-page="interests">Find your starting point ↗</button></div><div class="art" aria-hidden="true">✺</div></section><div class="note"><span>◇</span><div><b>You set the pace.</b> Share what you choose. A shared interest is an invitation to talk, never permission to act.</div></div><div class="sectionhead"><div><h2>People, beyond the profile.</h2><p>Explore sample connections and see how your preferences fit.</p></div><button class="subtle" data-page="profile">Edit my profile ↗</button></div><div class="toolbar"><div class="search"><input id="peopleSearch" aria-label="Search sample profiles" placeholder="Search interests, names or cities…" value="${esc(personQuery)}"></div><select id="goalFilter" aria-label="Relationship intention">${options(['All intentions','Friendship first','Long-term connection','Casual dating'],goal)}</select><select id="structureFilter" aria-label="Relationship structure">${options(['All structures','Monogamy','Polyamory','Open relationship','Consensual non-monogamy'],structure)}</select><select id="distanceFilter" aria-label="Illustrative distance">${[25,100,200].map(n=>`<option value="${n}"${n===distance?' selected':''}>Within ${n} miles*</option>`).join('')}</select></div><div id="peopleGrid" class="grid"></div><p class="statusline">* Sample distances from a fictional location. These are fictional adults, not live members. No location is requested.</p><div class="sectionhead"><h2>Good connection starts here.</h2></div><div class="grid">${[['◇','Consent, always','Yes is yes. No is no. You can change your mind at any time.'],['✺','Whole-person compatibility','Values, lifestyles, desires and boundaries all have a place.'],['♡','A judgement-free zone','Not your cup of tea? Walk on. Respect is non-negotiable.']].map(([icon,h,t])=>`<div class="card benefit"><div class="symbol">${icon}</div><div><h3>${h}</h3><p>${t}</p></div></div>`).join('')}</div>`}
function renderPeople(){const result=people.filter(p=>!state.blocked.includes(p.id)&&(!personQuery||[p.name,p.city,p.bio,...p.tags].join(' ').toLowerCase().includes(personQuery.toLowerCase()))&&p.distance<=distance&&(goal==='All intentions'||p.goal===goal)&&(structure==='All structures'||p.structure===structure));$('#peopleGrid').innerHTML=state.settings.paused?empty('Discovery is paused. Resume it in Privacy & settings.'):result.map(personCard).join('')||empty('No sample profiles match. Try a wider distance or fewer filters.')}
function field(label,name,type='text',placeholder=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(state.profile[name])}" placeholder="${esc(placeholder)}" ${name==='age'?'min="18" max="120"': 'maxlength="180"'}></label>`}
function profile(){let p=state.profile;return title('MY WHOLE SELF','A profile with room for you.','Identity, attraction, relationship structure and interests are separate. Choose the words that fit; every optional field can stay blank.')+`<form id="profileForm" class="stack"><section class="card"><h2>The introduction</h2><div class="formgrid">${field('Display name','name','text','A name you want people to use')}${field('Age · adults 18+','age','number')}${field('Pronouns','pronouns','text','e.g. they / them')}${field('City or region · no exact address','city')}${field('Gender · describe in your words','gender')}${field('Orientation · describe in your words','orientation','text','e.g. bisexual, asexual, demisexual')}<label>What brings you here?<select name="goal">${options(['Friendship first','Long-term connection','Casual dating','Companionship','Marriage minded','Exploring'],p.goal)}</select></label><label>Relationship structure<select name="structure">${options(['Monogamy','Consensual non-monogamy','Polyamory','Open relationship','Relationship anarchy','Exploring'],p.structure)}</select></label><label class="wide">The things a photo cannot tell you<textarea name="bio" maxlength="1500" placeholder="What makes you feel comfortable, understood and accepted?">${esc(p.bio)}</textarea></label></div></section><section class="card"><h2>The everyday things</h2><div class="formgrid">${field('Values & what matters','values')}${field('Lifestyle, smoking & drinking preferences','lifestyle')}${field('Family plans & children','children')}${field('Faith or worldview · optional','faith')}<label class="wide">Access & communication needs · optional<textarea name="access" maxlength="1000" placeholder="Share practical needs you want someone to know. No diagnosis required.">${esc(p.access)}</textarea></label></div></section><div class="note">This demo keeps edits in memory unless you enable Remember on this device. No profile is published. Avoid entering sensitive real information on a shared device.</div><div class="row"><button type="submit">Save my profile</button><button type="button" class="outline" data-page="interests">Add interests & desires ↗</button></div></form>`}
function saved(){return title('ROOM FOR A SECOND LOOK','Saved connections.','Save a sample profile to revisit it. Saving is private and does not create a match or send a notification.')+`<div class="grid">${people.filter(p=>state.saved.includes(p.id)&&!state.blocked.includes(p.id)).map(personCard).join('')||empty('No saved connections yet. Tap a heart in Discover to start.')}</div>`}
function messages(){let available=people.filter(p=>!state.blocked.includes(p.id));if(!available.some(p=>p.id===conversation))conversation=available[0]?.id;let p=available.find(p=>p.id===conversation);return title('COME HERE. LET’S HAVE A TALK.','Better conversations.','Try a conversation draft with an illustrative profile. Nothing is sent and there are no simulated replies pretending to be real people.')+`<div class="message-layout"><div class="conversationlist">${available.map(p=>`<button data-conversation="${p.id}" ${conversation===p.id?'style="box-shadow:inset 3px 0 #b36591"':''}>${p.symbol} ${p.name}<small>Demo · draft only</small></button>`).join('')}</div><div class="chat">${p?`<h3>${p.name} <small>Illustrative profile · not online</small></h3><div class="bubbles" id="bubbles">${(state.messages[p.id]||[]).map(m=>`<div class="bubble mine">${esc(m)}</div>`).join('')||'<p class="muted">Your conversation can start with curiosity.</p>'}</div><div class="tags">${['What helps you feel comfortable?','What boundaries matter to you?','What are you hoping to find?'].map(t=>`<button class="chip" data-prompt="${t}">${t}</button>`).join('')}</div><form id="messageForm"><input id="messageInput" maxlength="2000" aria-label="Draft message" placeholder="Write a respectful opening…" required><button>Save draft</button></form><small>Only a local draft. No message delivery service is connected.</small><button class="subtle" data-page="advisor">Help me find the words ↗</button>`:empty('All sample profiles are blocked. You can manage them in Respect & safety.')}</div></div>`}
function boundaries(){const b=state.boundaries;return title('YES IS YES. NO IS NO.','Boundaries make room for trust.','An interest or a past yes never replaces a current, freely given agreement. Silence and uncertainty are not permission. You can pause or stop at any point.')+`<form id="boundariesForm" class="stack"><div class="grid two"><section class="card"><h2>What feels right for me</h2>${[['yes','Things I am comfortable discussing'],['limits','My non-negotiable boundaries'],['discuss','Things to discuss before deciding'],['signals','How I communicate pause or stop']].map(([k,l])=>`<label>${l}<textarea name="${k}" maxlength="1200">${esc(b[k]||'')}</textarea></label>`).join('')}</section><section class="card"><h2>How I want to be treated</h2>${[['care','Reassurance, aftercare & personal space'],['digital','Photos, messages & digital boundaries'],['health','Topics for a private health conversation'],['access','Communication & access needs']].map(([k,l])=>`<label>${l}<textarea name="${k}" maxlength="1200">${esc(b[k]||'')}</textarea></label>`).join('')}</section></div><div class="note"><b>Always a conversation.</b> This is a private discussion worksheet, not a contract, waiver or permanent record of consent. A hard no is never something to overcome.</div><button type="submit">Save my private boundaries</button></form>`}
function planner(){let d=state.date;return title('A LITTLE THOUGHT GOES A LONG WAY','Make a thoughtful plan.','A private planning worksheet for your next conversation or date. No invitations, reminders or emergency alerts are sent.')+`<form id="plannerForm" class="grid two"><section class="card"><h2>The plan</h2><label>Plan title<input name="title" maxlength="150" value="${esc(d.title||'')}" placeholder="Coffee and a conversation"></label><label>Day & time<input type="datetime-local" name="time" value="${esc(d.time||'')}"></label><label>Meeting place<input name="place" maxlength="250" value="${esc(d.place||'')}" placeholder="A public place you both feel comfortable with"></label><label>Transport & exit plan<textarea name="transport" maxlength="1000">${esc(d.transport||'')}</textarea></label><label>Things to discuss<textarea name="notes" maxlength="1000">${esc(d.notes||'')}</textarea></label><button>Save my plan</button></section><section class="card"><h2>A comfort check</h2><div class="checklist">${['We have both agreed to the plan','We have discussed accessibility needs','I have arranged my own transport','I can leave or change my mind','I have chosen whether to tell a trusted person','We have discussed expectations without pressure'].map((t,i)=>`<label><input type="checkbox" name="check${i}" ${d['check'+i]?'checked':''}>${t}</label>`).join('')}</div><div class="note">This checklist records your own planning only. It does not verify another person’s agreement or provide live safety monitoring.</div></section></form>`}
function safety(){return title('JUDGEMENT FREE. RESPECT REQUIRED.','Mind your manners.','Everyone is an equal. No one owes a reply, an explanation, a photo, a meeting or access to their body.')+`<div class="grid two"><section class="card"><h2>Community standards</h2>${[['Adults only','This interface is intended for adults 18+. Age affirmation is not identity or age verification.'],['Consent & autonomy','Pressure, threats, harassment and coercion have no place here. A change of mind must be respected.'],['Privacy & dignity','Do not share another person’s messages, photos, location or identifying information without permission.'],['Consenting participants only','No minors, exploitation, animals, nonconsenting people or bystanders. Public visibility is not permission.'],['Honest participation','Do not impersonate people, run scams, solicit money or misrepresent relationship agreements.']].map(([h,t])=>`<details open><summary>${h}</summary><p>${t}</p></details>`).join('')}</section><section class="card"><h2>Report a concern</h2><p>Test the reporting workflow. Reports are local demo records and are not delivered to a moderation team.</p><form id="reportForm"><label>Sample profile<select name="person">${people.map(p=>`<option value="${p.id}">${p.name}</option>`).join('')}</select></label><label>Concern<select name="reason">${options(['Harassment or pressure','Privacy violation','Suspected underage account','Impersonation or scam','Unwanted content','Other'])}</select></label><label>Details<textarea name="details" maxlength="1500" required placeholder="Describe the concern without unnecessary personal information."></textarea></label><label class="row"><span>Also block this demo profile</span><input class="toggle" type="checkbox" name="block" checked></label><button>Create demo report</button></form><p class="statusline">${state.reports.length} demo reports recorded in this session or on this device.</p></section><section class="card"><h2>Blocked profiles</h2>${state.blocked.length?state.blocked.map(id=>`<div class="row setting"><span>${people.find(p=>p.id===id)?.name||'Unknown'}</span><button class="outline" data-unblock="${id}">Unblock</button></div>`).join(''):'<p>No blocked profiles.</p>'}</section><section class="card"><h2>Help beyond this demo</h2><p>If you are in immediate danger, contact local emergency services. This interface is not monitored.</p><a href="https://rainn.org/get-help" target="_blank" rel="noopener noreferrer">RAINN support resources ↗</a><p>US support for people affected by sexual violence.</p><a href="https://ncsfreedom.org/incident-reporting-response/" target="_blank" rel="noopener noreferrer">NCSF support & resources ↗</a></section></div>`}
function learn(){return title('CURIOSITY, WITH CONTEXT','Words are a starting point.','People use labels differently. Ask what a word means to the person using it. Identity is not a fetish, and attraction is not an obligation to act.')+`<div class="grid two"><section class="card"><h2>Get your bearings</h2>${[['Interest, kink & fetish','An interest is a broad preference. Kink is often used for nonconventional consensual interests. Fetish often refers to a particular focus of attraction. These everyday terms do not by themselves establish a clinical diagnosis.'],['Identity & attraction','Gender identity, orientation, romantic attraction and sexual interests are separate. Asexual and demisexual identities belong in identity discussions, not a list of fetishes.'],['Relationship agreements','Monogamy and consensual non-monogamy describe agreements. Having multiple partners is not a substitute for everyone knowing and agreeing to the arrangement.'],['Consent in context','Agreement is specific to a person, activity and situation. A profile selection, match, purchase, relationship or earlier agreement does not guarantee a present yes.'],['About the directory','This is an expandable editorial directory, not an exhaustive scientific taxonomy. Neutral descriptions are summarized in original words. Terms involving exploitation or nonconsenting participants are excluded. Custom buttons start private. You choose whether each appears in your profile preview.'],['Risk & expertise','Some listed interests carry physical or emotional risk. This directory provides no procedural instructions and makes no claim that an activity is safe. Use qualified, topic-specific education before considering unfamiliar activities.']].map(([h,t])=>`<details><summary>${h}</summary><p>${t}</p></details>`).join('')}</section><section class="card"><h2>Research & further reading</h2><p>Sources consulted October 7, 2026. These organizations do not endorse this app.</p><div class="linklist">${[['https://www.plannedparenthood.org/learn/relationships/sexual-consent','Planned Parenthood','Consent principles and communication'],['https://ncsfreedom.org/key-programs-2/consent-counts/','NCSF · Consent Counts','Consent, negotiation and context'],['https://ncsfreedom.org/resource-library/','NCSF · Resource Library','Terminology and consensual relationship resources'],['https://www.asexuality.org/?q=general.html','AVEN · General FAQ','Asexuality and distinctions between attraction and behavior'],['https://ncsfreedom.org/wp-content/uploads/2022/07/BDSM-Glossary-and-Resources.pdf','NCSF · BDSM Glossary','Primary terminology reference; individual usage can vary']].map(([url,n,t])=>`<a href="${url}" target="_blank" rel="noopener noreferrer">${n} ↗<small>${t}</small></a>`).join('')}</div></section></div>`}
function settings(){return title('YOUR INFORMATION. YOUR CHOICE.','Privacy starts with control.','The interface is a working browser demo. Your edits stay in this tab unless you explicitly choose browser storage. There are no live member accounts or cross-device sync. No tokens, credits, coins or paid unlocks are used.')+`<div class="grid two"><section class="card"><h2>Your controls</h2>${[['remember','Remember on this device','Save demo profile, preferences, drafts and reports in this browser. This is not encrypted secure storage; use sample information.'],['discreet','Discreet display','Blur directory entries when someone may be looking at your screen.'],['paused','Pause discovery','Hide sample discovery results until you choose to return.']].map(([k,h,t])=>`<div class="row setting"><div><h3>${h}</h3><p>${t}</p></div><input type="checkbox" class="toggle" data-setting="${k}" aria-label="${h}" ${state.settings[k]?'checked':''}></div>`).join('')}<div class="note">No GPS, advertising trackers, image uploads or member data sharing. Fonts may load from Google Fonts. Your browser and hosting service still process normal page requests.</div></section><section class="card"><h2>Manage your data</h2><p>Export your demo data as JSON. The export may include private text you entered; choose where you keep it carefully.</p><button class="outline" id="export">Export my demo data</button><hr style="border:0;border-top:1px solid var(--line);margin:25px 0"><h3>Start fresh</h3><p>Delete this demo’s profile, choices, saved profiles, drafts, reports and plans from memory and browser storage.</p><button class="outline danger" id="delete">Delete all demo data</button></section><section class="card wide"><h2>What this version does — and what comes next</h2><p><b>Working now:</b> searchable directory, editable profile, preferences and visibility choices, discovery filters, saved profiles, draft conversations, boundary worksheet, date plan, demo reports, blocking, export and deletion.</p><p><b>Production work still required:</b> real account and adult verification, protected server storage, field-level sharing enforcement, actual matching and message delivery, moderation operations, abuse prevention, media controls, consent-focused onboarding, security testing, accessibility review and jurisdiction-specific privacy/terms review. No interface can guarantee consent or prevent all misconduct.</p><p>No tokens, credits, coins, subscriptions or payments are collected. One added button increases your selection count by one; one removed button decreases it by one. Counts are not compatibility scores. No claim is made that moderation or identity verification is active.</p></section></div>`}
function about(){return title('TA 🪭 DA 🎉','Taters & Daters.','The Tabor Assistant Dating App — a concept founded by Nathan Tabor.')+`<section class="hero"><div><div class="eyebrow">THE APP THAT ENDS ALL DATING APPS</div><h1>Be yourself.<br><em>Respect each other.</em></h1><p>“Intimacy is respect. Intimacy is equals. Intimacy is listening.”</p></div><div class="art">♡</div></section><div class="grid two" style="margin-top:20px"><div class="card"><h2>The idea</h2><p>A place to say what matters before a relationship becomes a guessing game. Honest disclosure is voluntary. Every person keeps their own boundaries.</p><p>Not your cup of tea? Walk on. Come here… let’s you and me have a TALK.</p><p>Founder’s alternate acronym: “The Tits Ass Detailed Algorithm.”</p></div><div class="card"><h2>The founder</h2><p>Nathan Tabor · 8/29/1973<br>PK · IFB · KJV · BB3 · HA · LU · FU</p><p>Founder-provided background:<br>BA in Psychology — emphasis Abnormal Sexual Behaviors<br>MA in Public Policy — emphasis Constitutional Law<br>Honorary PhD in Intercity Evangelism</p><small>Founder details are supplied by the founder and are not independently verified. No professional services are offered here.</small></div></div>`}
function render(){page=location.hash.slice(1)||'interests';const pages={discover,interests:catalog,profile,saved,messages,boundaries,planner,safety,learn,settings,about,board,almanac,knowledge,advisor,intent,languages};if(!pages[page])page='discover';$('#nav').innerHTML=nav.map(([id,icon,label])=>`${id==='almanac'?'<div class="navdivider">YOUR SIDEKICKS</div>':''}<button data-page="${id}" class="${id===page?'active':''}" ${id===page?'aria-current="page"':''}><span class="icon" aria-hidden="true">${icon}</span>${label}</button>`).join('');$('#breadcrumb').textContent=nav.find(n=>n[0]===page)?.[2]||'The TA DA story';$('#main').innerHTML=pages[page]();if(page==='discover')renderPeople();if(page==='interests')renderCatalog();if(page==='profile')$('#main').innerHTML+=profileButtonSection();persist();applyLocale();window.scrollTo(0,0)}
function showPerson(id){const p=people.find(p=>p.id===id);if(!p)return;modal(`<div class="eyebrow">ILLUSTRATIVE ADULT PROFILE</div><h2 style="margin-top:15px">${p.name}, ${p.age}</h2><p class="muted">${p.pronouns} · ${p.city}</p><p>${p.bio}</p><div class="tags">${p.tags.map(t=>`<span class="tag">${t}</span>`).join('')}</div><p><b>Looking for:</b> ${p.goal}<br><b>Relationship agreement:</b> ${p.structure}</p><div class="note">Compatibility is a conversation, not a score. These sample preferences do not imply consent.</div><div class="row"><button data-chat="${p.id}">Draft a conversation</button><button class="outline" data-block="${p.id}">Block demo profile</button></div>`)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.page)go(b.dataset.page);if(b.dataset.category){category=b.dataset.category;render();}if(b.dataset.save){let id=b.dataset.save;state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];persist();if(page==='discover')renderPeople();else render();toast(state.saved.includes(id)?'Saved privately':'Removed from saved')}if(b.dataset.person)showPerson(b.dataset.person);if(b.dataset.chat){conversation=b.dataset.chat;$('#modal').close();go('messages')}if(b.dataset.conversation){conversation=b.dataset.conversation;render()}if(b.dataset.prompt){$('#messageInput').value=b.dataset.prompt;$('#messageInput').focus()}if(b.dataset.block){state.blocked.push(b.dataset.block);state.saved=state.saved.filter(id=>id!==b.dataset.block);persist();$('#modal').close();render();toast('Demo profile blocked')}if(b.dataset.unblock){state.blocked=state.blocked.filter(id=>id!==b.dataset.unblock);persist();render();toast('Demo profile unblocked')}if(b.id==='export'){let blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='ta-da-private-demo-data.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Export prepared')}if(b.id==='delete')modal('<h2>Delete all demo data?</h2><p>This removes your demo profile, preferences, messages, reports and plan from this tab and this browser. It cannot be undone.</p><button id="confirmDelete">Delete everything</button>');if(b.id==='confirmDelete'){advisorRun++;state=defaults();translator?.destroy();translator=null;translateEpoch++;localStorage.removeItem('tada-demo');$('#modal').close();render();toast('All demo data deleted')}if(b.id==='enterApp'){sessionStorage.setItem('tada-adult','yes');$('#modal').close()}if(b.id==='leaveApp'){location.replace('https://www.google.com/')}});
document.addEventListener('input',e=>{if(e.target.id==='interestSearch'){query=e.target.value;renderCatalog()}if(e.target.id==='peopleSearch'){personQuery=e.target.value;renderPeople()}});
document.addEventListener('change',e=>{let t=e.target;if(t.dataset.pref){let id=t.dataset.pref;state.prefs[id]={interest:'Not specified',visibility:'Only me',...state.prefs[id],[t.dataset.field]:t.value};if(state.prefs[id].interest==='Not specified'&&state.prefs[id].visibility==='Only me')delete state.prefs[id];persist();if($('#prefTotal'))$('#prefTotal').textContent=Object.keys(state.prefs).length;if(prefFilter!=='All preferences')renderCatalog();toast('Preference saved privately')}if(t.id==='prefFilter'){prefFilter=t.value;renderCatalog()}if(t.id==='goalFilter'){goal=t.value;renderPeople()}if(t.id==='structureFilter'){structure=t.value;renderPeople()}if(t.id==='distanceFilter'){distance=Number(t.value);renderPeople()}if(t.dataset.setting){state.settings[t.dataset.setting]=t.checked;persist();toast('Setting updated')}});
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target,values=Object.fromEntries(new FormData(form));if(form.id==='profileForm'){if(values.age&&(Number(values.age)<18||Number(values.age)>120)){toast('This interface is for adults 18+.');return}state.profile=values;persist();toast('Profile saved in your demo workspace')}if(form.id==='messageForm'){let text=$('#messageInput').value.trim();if(!text)return;(state.messages[conversation]??=[]).push(text);persist();render();toast('Draft saved. Nothing was sent.')}if(form.id==='boundariesForm'){state.boundaries=values;persist();toast('Private boundaries saved')}if(form.id==='plannerForm'){state.date=values;persist();toast('Date plan saved. No invitation or alert sent.')}if(form.id==='reportForm'){state.reports.push({...values,createdAt:new Date().toISOString()});if(values.block&&!state.blocked.includes(values.person))state.blocked.push(values.person);persist();render();toast('Demo report saved locally. Not sent to moderators.')}});
window.addEventListener('hashchange',render);render();
if(sessionStorage.getItem('tada-adult')!=='yes'){modal(`<div class="eyebrow">WELCOME TO TA DA</div><h2 style="margin-top:16px">Honesty starts here.</h2><p class="intro">This is an adult dating app interface with non-graphic discussions of relationships and personal interests.</p><div class="note">Working demo · fictional profiles · no live messages or moderation. Use sample information while exploring.</div><p>By entering, you confirm that you are 18 or older and will respect other people’s boundaries. This age affirmation is not verification.</p><button id="enterApp" class="full">I’m 18 or older — explore the app</button><button id="leaveApp" class="subtle full">Leave</button>`);$('#modal .close').remove();$('#modal').addEventListener('cancel',e=>{if(sessionStorage.getItem('tada-adult')!=='yes')e.preventDefault()})}

// Personal button library. Original implementation; no third-party site code.
function categoryList(){return [...new Set(['Kink & sensory interests','Roles & dynamics','Clothing & materials','Fantasy & expression','Roleplay & adult personas','Specific textures & objects','Attraction preferences','Aesthetics & subcultures','Environment & pace','Connection & affection','Relationship structure','Negotiated relationship rituals','Care & communication','Digital connection',...allInterests().map(i=>i.category)])]}
function selectedButtons(){return allInterests().filter(i=>state.prefs[i.id]&&state.prefs[i.id].interest!=='Not specified')}
function setChoice(id,value){state.prefs[id]={visibility:'Only me',...state.prefs[id],interest:value};persist()}
function toggleButton(id){if(state.prefs[id]?.interest&&state.prefs[id].interest!=='Not specified'){delete state.prefs[id];toast('−1 button removed')}else{setChoice(id,'Interested');toast('+1 button added · private until you choose to share')}persist()}
function catalog(){const count=selectedButtons().length;return datingHero()+`<div class="librarybanner"><div><strong>1 + 1 = 2 <span>·</span> 1 − 1 = 0</strong><p>One tap adds. One tap removes. No tokens. No credits. No hidden scores.</p></div><button data-page="board" class="outline">My ${count} buttons ↗</button></div><div class="sectionhead categoryheading"><div><div class="eyebrow">BE CURIOUS. BE HONEST. BE YOU.</div><h2>Find your kind of chemistry.</h2><p>Interests, kinks, fetishes and everything that makes a connection yours.</p></div><span class="categorycount">${categoryList().length} sections · ${allInterests().length} starting points</span></div><div class="categorytiles">${categoryList().map((g,k)=>`<button class="categorytile ${category===g?'active':''}" data-category="${esc(g)}"><span class="tileicon" aria-hidden="true">${['✺','♛','👠','🎭','🪭','🎀','♡','✧','🌙','♥','∞','◇','☕','💌'][k%14]}</span><strong>${esc(g)}</strong><small>${allInterests().filter(i=>i.category===g).length} buttons <span aria-hidden="true">↗</span></small></button>`).join('')}</div><div class="librarytools"><div class="toolbar"><div class="search"><input id="interestSearch" placeholder="Search any interest, material or dynamic…" aria-label="Search interests" value="${esc(query)}"></div><button id="addInterest">+ Create a button</button></div><div class="row wrap"><div class="tabs"><button class="chip ${category==='All'?'active':''}" data-category="All">All sections</button><select id="prefFilter" aria-label="Filter interests">${options(['All preferences','My choices','Interested','Curious','Discuss first','Hard no'],prefFilter)}</select><select id="librarySort" aria-label="Sort interests">${options(['Category','A–Z'],sortMode)}</select></div><div class="tabs"><button class="chip ${viewMode==='buttons'?'active':''}" data-view="buttons" aria-pressed="${viewMode==='buttons'}">Buttons</button><button class="chip ${viewMode==='details'?'active':''}" data-view="details" aria-pressed="${viewMode==='details'}">Definitions</button></div></div></div><div class="sectionhead"><div><h2>${esc(category==='All'?'The full library':category)}</h2><div id="catalogcount" class="catalogcount" role="status"></div></div><button class="subtle" id="previewProfile">Preview my profile ↗</button></div><div id="catalogGrid" class="sensitive"></div><div class="note"><b>Your consent stays yours.</b><span>Every selection starts private. Change interest level and visibility through its edit control. Identity and relationship structure are separate from fetish categories. This is an expandable directory, not a claim to list every possible interest.</span></div><p class="statusline">${allInterests().length} terms · ${categoryList().length} sections · Original, non-graphic editorial descriptions. <a href="#learn">Research & sources</a></p>`}
function renderCatalog(){let filtered=allInterests().filter(i=>(category==='All'||i.category===category)&&(!query||[i.name,i.description,i.category,...(i.aliases||[])].join(' ').toLowerCase().includes(query.toLowerCase()))&&(prefFilter==='All preferences'||(prefFilter==='My choices'?state.prefs[i.id]&&state.prefs[i.id].interest!=='Not specified':state.prefs[i.id]?.interest===prefFilter)));if(sortMode==='A–Z')filtered.sort((a,b)=>a.name.localeCompare(b.name));$('#catalogcount').textContent=`${filtered.length} results · ${selectedButtons().length} selected · no compatibility scoring`;$('#catalogGrid').className=viewMode==='details'?'grid two sensitive':'buttonlibrary sensitive';$('#catalogGrid').innerHTML=filtered.map(i=>{const p=state.prefs[i.id]||{},chosen=p.interest&&p.interest!=='Not specified';return viewMode==='buttons'?`<div class="interestbutton ${chosen?'chosen':''} ${p.interest==='Hard no'?'hardno':''}"><button class="interesttoggle" data-toggle-interest="${esc(i.id)}" aria-pressed="${!!chosen}"><span class="buttonmark" aria-hidden="true">${chosen?'✓':'+'}</span><span>${esc(i.name)}<small>${chosen?esc(p.interest)+' · '+esc(p.visibility||'Only me'):esc(i.category)}</small></span></button><button class="buttonedit" data-edit-interest="${esc(i.id)}" aria-label="Edit ${esc(i.name)}">⋯</button></div>`:`<article class="card"><div class="prefrow"><div><div class="cat">${esc(i.category)}</div><h3>${esc(i.name)}</h3><p>${esc(i.description)}</p></div><button class="buttonedit" data-edit-interest="${esc(i.id)}" aria-label="Edit ${esc(i.name)}">⋯</button></div><div class="prefselect"><label>Your interest<select data-pref="${esc(i.id)}" data-field="interest">${options(['Not specified','Interested','Curious','Discuss first','Hard no'],p.interest||'Not specified')}</select></label><label>Visibility<select data-pref="${esc(i.id)}" data-field="visibility">${options(['Only me','Matches only','On my profile'],p.visibility||'Only me')}</select></label></div></article>`}).join('')||empty('No buttons match. Try another search, or create your own using “Create a button”.')}
function editInterest(id){let i=id?allInterests().find(i=>i.id===id):null,p=i?(state.prefs[id]||{}):{};modal(`<div class="eyebrow">${i?'MAKE IT YOUR OWN':'ONE MORE WAY TO SAY WHO YOU ARE'}</div><h2 style="margin-top:15px">${i?'Edit your button.':'Create a button.'}</h2><p class="muted">Your personal wording changes only your library. Keep descriptions non-graphic and about consenting adults.</p><form id="buttonForm" data-id="${esc(id||'')}"><label>Button name<input name="name" required maxlength="70" value="${esc(i?.name||'')}" placeholder="Your word or preference"></label><label>Section<input name="category" list="categoryNames" required maxlength="70" value="${esc(i?.category||(category==='All'?'My own terms':category))}" placeholder="Choose or create a section"><datalist id="categoryNames">${categoryList().map(g=>`<option value="${esc(g)}">`).join('')}</datalist></label><label>What it means to you<textarea name="description" required maxlength="400" placeholder="Explain it in your own words.">${esc(i?.description||'')}</textarea></label><div class="formgrid"><label>Your interest<select name="interest">${options(['Interested','Curious','Discuss first','Hard no','Not specified'],p.interest||'Interested')}</select></label><label>Show this button to<select name="visibility">${options(['Only me','Matches only','On my profile'],p.visibility||'Only me')}</select></label></div><div class="note">“On my profile” adds it to your profile preview. This browser demo does not publish a member profile or synchronize it with other people.</div><button class="full">${i?'Save my changes':'Create & add my button'}</button></form>${i?`<div class="row" style="margin-top:16px"><button class="subtle danger" data-remove-interest="${esc(id)}">Remove from my selection</button>${state.custom.some(x=>x.id===id)?`<button class="subtle danger" data-delete-interest="${esc(id)}">Delete custom button</button>`:`<button class="subtle" data-reset-interest="${esc(id)}">Restore original wording</button>`}</div>`:''}`)}
function previewButtons(audience){return selectedButtons().filter(i=>audience==='Only me'||state.prefs[i.id].visibility==='On my profile'||(audience==='Matches only'&&state.prefs[i.id].visibility==='Matches only'))}
function profilePreviewContent(audience){const items=previewButtons(audience);return `<div class="profilepreview"><div class="avatar">${esc((state.profile.name||'Y').slice(0,1).toUpperCase())}</div><h2>${esc(state.profile.name||'Your profile')}${state.profile.age?', '+esc(state.profile.age):''}</h2><p class="muted">${esc(state.profile.bio||'Your introduction goes here.')}</p><div class="previewchips">${items.map(i=>`<div class="previewchip ${state.prefs[i.id].interest==='Hard no'?'hardno':''}"><strong>${esc(i.name)}</strong><small>${esc(state.prefs[i.id].interest)}</small></div>`).join('')||'<p class="muted">No buttons visible to this audience. Set a button’s visibility to add it here.</p>'}</div><p class="statusline">${items.length} visible buttons · ${audience==='Only me'?'Owner view includes private choices.':'Private choices are excluded.'} Selections are not consent.</p></div>`}
function showPreview(){modal(`<div class="eyebrow">PROFILE PREVIEW · NOT PUBLISHED</div><h2 style="margin-top:15px">See what you share.</h2><label>Preview as<select id="previewAudience">${options(['On my profile','Matches only','Only me'],previewAudience)}</select></label><div id="previewBody">${intentPreview(previewAudience)}${profilePreviewContent(previewAudience)}</div>`)}
function profileButtonSection(){return `<section class="card" style="margin-top:24px"><div class="sectionhead" style="margin-top:0"><div><h2>My profile buttons</h2><p>Your chosen words, with your chosen visibility.</p></div><button type="button" id="previewProfile" class="outline">Preview audiences</button></div>${intentPreview('On my profile')}${profilePreviewContent('On my profile')}<button data-page="board" class="subtle">Manage all my buttons ↗</button></section>`}
function board(){const items=selectedButtons();return title('YOUR PERSONAL BUTTON BOARD','Build your own vocabulary.','Add, edit, organize and remove your interests. A custom section appears automatically when you create a button in it. Your words belong to you.')+`<div class="librarybanner"><div><strong>${items.length} selected buttons</strong><p>1 + 1 = 2 · 1 − 1 = 0 · No tokens. No credits. No scores.</p></div><button id="addInterest">+ Create a button</button></div><div class="toolbar"><button id="previewProfile" class="outline">Preview my profile ↗</button><button data-page="interests" class="outline">Browse the library</button></div><div class="grid two sensitive">${items.map(i=>`<article class="card"><div class="cat tiny">${esc(i.category)}</div><h3 style="margin-top:12px">${esc(i.name)}</h3><p>${esc(i.description)}</p><div class="tags"><span class="tag">${esc(state.prefs[i.id].interest)}</span><span class="tag">${esc(state.prefs[i.id].visibility||'Only me')}</span>${state.custom.some(x=>x.id===i.id)?'<span class="tag">Custom button</span>':''}</div><div class="row"><button class="outline" data-edit-interest="${esc(i.id)}">Edit button</button><button class="subtle danger" data-remove-interest="${esc(i.id)}">− Remove</button></div></article>`).join('')||empty('No selected buttons yet. Browse the library or create your first button.')}</div><div class="note">Your changes stay in this tab unless you enable <a href="#settings">Remember on this device</a>. Public access to this website does not make your personal demo data public.</div>`}
function refreshLibrary(){persist();if(page==='interests')render();else if(page==='board'||page==='profile')render()}
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.id==='addInterest')editInterest();if(b.dataset.toggleInterest){toggleButton(b.dataset.toggleInterest);renderCatalog();let count=$('.librarybanner button');if(count)count.textContent=`My ${selectedButtons().length} buttons ↗`}if(b.dataset.editInterest)editInterest(b.dataset.editInterest);if(b.dataset.view){viewMode=b.dataset.view;render()}if(b.id==='previewProfile')showPreview();if(b.dataset.removeInterest){delete state.prefs[b.dataset.removeInterest];if($('#modal').open)$('#modal').close();refreshLibrary();toast('−1 selection removed. The button stays in your library.')}if(b.dataset.deleteInterest){const id=b.dataset.deleteInterest;modal(`<h2>Delete your custom button?</h2><p>It will be removed from your library and profile preview.</p><button data-confirm-delete-button="${esc(id)}">Delete custom button</button>`)}if(b.dataset.confirmDeleteButton){const id=b.dataset.confirmDeleteButton;state.custom=state.custom.filter(i=>i.id!==id);delete state.prefs[id];$('#modal').close();if(!categoryList().includes(category))category='All';refreshLibrary();toast('Custom button deleted')}if(b.dataset.resetInterest){delete state.overrides?.[b.dataset.resetInterest];persist();editInterest(b.dataset.resetInterest)}});
document.addEventListener('change',e=>{let t=e.target;if(t.id==='librarySort'){sortMode=t.value;renderCatalog()}if(t.id==='previewAudience'){previewAudience=t.value;$('#previewBody').innerHTML=intentPreview(previewAudience)+profilePreviewContent(previewAudience)}if(t.dataset.pref&&page==='interests')renderCatalog()});
document.addEventListener('submit',e=>{if(e.target.id!=='buttonForm')return;e.preventDefault();let form=e.target,v=Object.fromEntries(new FormData(form)),id=form.dataset.id;for(const key of ['name','description','category'])v[key]=v[key].trim();if(!v.name||!v.description||!v.category){toast('Please complete the name, section and description.');return}if(allInterests().some(i=>i.id!==id&&i.name.toLowerCase()===v.name.toLowerCase())){toast('That button name already exists. Choose another name or edit it.');return}const item={name:v.name,description:v.description,category:v.category};if(id){let custom=state.custom.find(i=>i.id===id);if(custom)Object.assign(custom,item);else{state.overrides??={};state.overrides[id]=item}}else{id='custom-'+crypto.randomUUID();state.custom.push({id,...item})}state.prefs[id]={interest:v.interest,visibility:v.visibility};persist();$('#modal').close();category=v.category;query='';prefFilter='All preferences';refreshLibrary();toast('Button saved. Preview your profile to see its visibility.')});

function datingHero(){return `<section class="datinghero"><div class="datingherocopy"><div class="eyebrow">TA 🪭 DA 🎉 · TATERS & DATERS</div><h1>A little spice.<br><em>A lot more you.</em></h1><p>Your interests. Your boundaries. Your kind of connection.<br>Skip the guessing games. Start with who you are.</p><div class="herobuttons"><button data-page="discover">Find your people ↗</button><button data-page="advisor" class="herooutline">Talk to your advisor ✦</button></div><div class="herochips"><span>18+ only</span><span>No tokens. No pay-to-play.</span><span>Consent comes first.</span></div></div><div class="brandillustration" aria-hidden="true"><div class="orbit orbitone"></div><div class="orbit orbittwo"></div><div class="floatingheart">♥</div><div class="fanart">${Array.from({length:11},(_,i)=>`<i style="--turn:${i*15-75}deg;--hue:${315+i*4}"></i>`).join('')}<b>✦</b></div><span class="artpotato">🥔</span><span class="artspark">✧</span><span class="artcaption">GOOD PEOPLE.<br>GREAT CHEMISTRY.</span></div></section><div class="quickpaths"><button data-page="profile"><span>◉</span><div><b>Show your whole self</b><small>More than a profile photo</small></div><span>↗</span></button><button data-page="board"><span>✺</span><div><b>Your own buttons</b><small>Create. Customize. Choose.</small></div><span>↗</span></button><button data-page="intent"><span>◷</span><div><b>What feels right today?</b><small>Your pace can change</small></div><span>↗</span></button></div>`}
